// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The list displayed at the nursing stations and in the pharmacy (MSDS 56 ii). */
export interface HighAlertListOut {
  /** The categories that have medicines, in a fixed order */
  categories: HighAlertCategoryOut[];
  restricted: SafetyDrugOut[];
  lasa_pairs: LasaPairOut[];
}

export interface HighAlertCategoryOut {
  category: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other";
  label: string;
  drugs: SafetyDrugOut[];
}

/** A formulary medicine with its safety flags. */
export interface SafetyDrugOut {
  drug_id: number;
  code: string;
  name: string;
  generic_name: string | null;
  strength: string | null;
  form: "Tablet" | "Capsule" | "Syrup" | "Suspension" | "Injection" | "Infusion" | "Cream" | "Ointment" | "Drops" | "Inhaler" | "Suppository" | "Powder" | "Consumable" | "Device" | "Other";
  schedule: "OTC" | "ScheduleG" | "ScheduleH" | "ScheduleX" | "HospitalOnly";
  /** Set: a high-alert medicine (a second person checks it when it is dispensed and when it is given) */
  high_alert_category: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other" | null;
  /** Prescribed only with the RestrictedPrescribing privilege */
  is_restricted: boolean;
  is_otc_allowed: boolean;
  is_active: boolean;
  row_version: number;
  /** The medicines it looks or sounds like */
  lasa_with: string[];
}

export interface LasaPairOut {
  pair_id: number;
  drug_id: number;
  drug_name: string;
  drug_strength: string | null;
  other_drug_id: number;
  other_drug_name: string;
  other_drug_strength: string | null;
  /** What looks or sounds alike, and how to tell them apart */
  note: string;
  is_active: boolean;
  created_at: string;
  row_version: number;
}

export interface DrugSafetyIn {
  /** Null: not a high-alert medicine */
  high_alert_category?: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other" | null;
  /** Prescribed only with the RestrictedPrescribing privilege */
  is_restricted?: boolean | null;
  expected_version?: number | null;
}

export interface LasaPairIn {
  drug_id: number;
  other_drug_id: number;
  /** What looks or sounds alike, and how to tell them apart */
  note: string;
}

export interface LasaPairUpdateIn {
  note?: string | null;
  /** false retires the pair */
  is_active?: boolean | null;
  expected_version?: number | null;
}

/** A drug with its live stock (view v_drug_stock): what e-prescription search shows. */
export interface DrugStockOut {
  drug_id: number;
  code: string;
  name: string;
  generic_name: string | null;
  strength: string | null;
  form: "Tablet" | "Capsule" | "Syrup" | "Suspension" | "Injection" | "Infusion" | "Cream" | "Ointment" | "Drops" | "Inhaler" | "Suppository" | "Powder" | "Consumable" | "Device" | "Other";
  unit: string;
  schedule: "OTC" | "ScheduleG" | "ScheduleH" | "ScheduleX" | "HospitalOnly";
  is_otc_allowed: boolean;
  barcode: string | null;
  low_stock_threshold: number;
  is_active: boolean;
  /** Set: a high-alert medicine (MSDS 56): show it in red; a second person checks it when dispensed and given */
  high_alert_category: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other" | null;
  /** Prescribed only with the RestrictedPrescribing privilege (MSDS 52) */
  is_restricted: boolean;
  /** Medicines it looks or sounds like: warn when one is picked */
  lasa_with: string[];
  /** Non-expired stock */
  qty_available: number;
  next_expiry: string | null;
  /** OutOfStock: show the drug greyed out */
  stock_status: "InStock" | "Low" | "OutOfStock";
}

/** The high-alert, restricted and look-alike medicines — GET /api/v1/medication-safety/high-alert-list (who may call: holders of medication.safety.view or medication.safety.configure). */
export function highAlertList(): Promise<HighAlertListOut> {
  return api<HighAlertListOut>("GET", `/medication-safety/high-alert-list`, undefined);
}

/** The high-alert list to display, as a PDF — GET /api/v1/medication-safety/high-alert-list/pdf (who may call: holders of medication.safety.view or medication.safety.configure). */
export function highAlertPdf(): Promise<unknown> {
  return api<unknown>("GET", `/medication-safety/high-alert-list/pdf`, undefined);
}

/** Set a medicine's high-alert category or restriction — PATCH /api/v1/medication-safety/drugs/{drug_id} (who may call: holders of medication.safety.configure). */
export function setDrugFlags(drug_id: number, body: DrugSafetyIn): Promise<SafetyDrugOut> {
  return api<SafetyDrugOut>("PATCH", `/medication-safety/drugs/${drug_id}`, body);
}

/** Pair two look-alike or sound-alike medicines — POST /api/v1/medication-safety/lasa-pairs (who may call: holders of medication.safety.configure). */
export function addPair(body: LasaPairIn): Promise<LasaPairOut> {
  return api<LasaPairOut>("POST", `/medication-safety/lasa-pairs`, body, { idempotent: true });
}

/** Change or retire a look-alike pair — PATCH /api/v1/medication-safety/lasa-pairs/{pair_id} (who may call: holders of medication.safety.configure). */
export function updatePair(pair_id: number, body: LasaPairUpdateIn): Promise<LasaPairOut> {
  return api<LasaPairOut>("PATCH", `/medication-safety/lasa-pairs/${pair_id}`, body);
}

/** The written medication policy as a PDF — GET /api/v1/medication-safety/policy/pdf (who may call: holders of medication.safety.view or medication.safety.configure). */
export function policyPdfMedicationSafety(): Promise<unknown> {
  return api<unknown>("GET", `/medication-safety/policy/pdf`, undefined);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}
